// To try it, copy it to tests/unit/ and run `npx vitest run tests/unit`.
import { describe, expect, it } from 'vitest';
import { createTestApp, SLOT_WED_18 } from '../helpers';

describe('WaitlistService.promoteNext', () => {
  it('promotes the earliest waitlisted user when a slot frees up', async () => {
    const { login, hold, post, notifier } = createTestApp();
    const alice = await login('alice');
    const id = (await hold(alice, SLOT_WED_18)).json().booking.id;
    await post(alice, `/bookings/${id}/confirm`);

    await post(await login('bob'), `/slots/${SLOT_WED_18}/waitlist`);
    await post(await login('carol'), `/slots/${SLOT_WED_18}/waitlist`);

    await post(alice, `/bookings/${id}/cancel`);

    expect(notifier.sent).toHaveLength(1);
    expect(['user-bob', 'user-carol']).toContain(notifier.sent[0].userId);
    expect(notifier.sent[0].message).toContain(SLOT_WED_18);
  });

  it('does nothing when nobody is waiting', async () => {
    const { services } = createTestApp();
    expect(services.waitlist.promoteNext(SLOT_WED_18)).toBeUndefined();
  });

  it('marks the promoted entry as offered', async () => {
    const { login, post, services } = createTestApp();
    await post(await login('bob'), `/slots/${SLOT_WED_18}/waitlist`);

    const promoted = services.waitlist.promoteNext(SLOT_WED_18);

    expect(promoted).toBeDefined();
    expect(services.repos.waitlist.findById(promoted!.id)?.status).toBe('OFFERED');
  });
});
